import React from 'react';
import {AbsoluteFill, Img} from 'remotion';
export type HQComicPageOptions = {backgroundStyle?:'comic_page'; backgroundOpacity?:number};
// Exact supplied PNG, embedded once per installed project; no network or extra assets.
const PAGE='data:image/png;base64,';
export function HQComicPage({opacity=100}:{opacity?:number}) {
  if(!Number.isFinite(opacity)||opacity<0||opacity>100)throw Error('backgroundOpacity: 0–100 (%).');
  return <AbsoluteFill style={{pointerEvents:'none',opacity:opacity/100,overflow:'hidden'}}>
    <Img src={PAGE} style={{width:'100%',height:'100%',objectFit:'cover',objectPosition:'center'}}/>
  </AbsoluteFill>;
}
